INSERT INTO seekers(id,name,email,email_normalized,rings_pursued,created_at) SELECT 'member-talia-identity','Talia Emberborn','talia.emberborn@gmail.com','talia.emberborn@gmail.com','[]',unixepoch() WHERE NOT EXISTS(SELECT 1 FROM seekers WHERE email_normalized='talia.emberborn@gmail.com');
INSERT INTO member_profiles(id,seeker_id,draft,published,leadership,updated_at) SELECT 'talia-emberborn',id,'{"name": "Talia Emberborn", "introduction": "Keeper of the Current and High Priestess. She set out to stop being a weapon—and found a faith in the bonds between living souls.", "current_role": "Keeper of the Current · High Priestess", "hynafol_title": "Mother of Fire · Phoenix Reborn", "honours": "", "affiliations": "Independent Keeper; personally of the Court of Valor", "portrait": "/assets/img/talia-editorial-v2.jpg", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn", "story": "Before Hynafol\n\nTalia was born to scholars: a historian-warrior mother and a philosopher father. The Children of the Ash came to their village seeking the blood in their daughter’s veins. Her parents died protecting a secret they had not yet explained to her.\n\nThe Phoenix’s Ghost\n\nGrief drove Talia to train with a weapons master. When she returned to her village, she found the cult living in her family’s home—and her mother’s red-and-black armour waiting in its basement. She hunted the Children of the Ash until their last compound burned around her.\n\nThe fire did not harm her. Flames parted around her, and she understood what her parents had died protecting: she was Emberborn, touched by Ignus. She left her old home, uncertain who she could become beyond the weapon she had made of herself.\n\nSix strangers, six lessons\n\nOn the road, Kira, a merchant’s daughter, showed her what cooperation could accomplish. An arthritic healer taught her that sanctuary can be made through presence rather than force. A grieving farmer and a preserved lemon gave her a way to understand bitterness as something that could be transformed.\n\nA mercenary captain showed her the strength of shared purpose. A philosophy scholar asked her to find the principle beneath the technique. A monastery abbot asked who she might be after violence. In that silence, she began to hear a current beneath her fear.\n\nBeyond the mists\n\nWhen Talia entered Hynafol, the fire in her blood awakened fully. Later, a rediscovered manuscript gave a name to the lessons she had already been living. The Current had not given her those experiences; it had given her a way to bring them together.\n\nShe now tends the faith’s sacred objects, its Circles and its seekers. Her personal oath to the Court of Valor does not bind the Current or its members. Within the faith, many allegiances may gather without surrendering their own paths.\n\nThe story continues\n\nAt the November 2025 Grand Gathering, the working for Ophelia’s heart revealed Talia’s Emberborn nature publicly. The Keeper’s Beacon followed in February 2026. At the March 2026 Trials expedition, she rose after an assassination and stood for the Unity Mead that evening.\n\nThis introduction is drawn from Talia’s Hynafol wiki biography. The complete account—including the workings and their witnesses—continues at the link below."}','{"name": "Talia Emberborn", "introduction": "Keeper of the Current and High Priestess. She set out to stop being a weapon—and found a faith in the bonds between living souls.", "current_role": "Keeper of the Current · High Priestess", "hynafol_title": "Mother of Fire · Phoenix Reborn", "honours": "", "affiliations": "Independent Keeper; personally of the Court of Valor", "portrait": "/assets/img/talia-editorial-v2.jpg", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn", "story": "Before Hynafol\n\nTalia was born to scholars: a historian-warrior mother and a philosopher father. The Children of the Ash came to their village seeking the blood in their daughter’s veins. Her parents died protecting a secret they had not yet explained to her.\n\nThe Phoenix’s Ghost\n\nGrief drove Talia to train with a weapons master. When she returned to her village, she found the cult living in her family’s home—and her mother’s red-and-black armour waiting in its basement. She hunted the Children of the Ash until their last compound burned around her.\n\nThe fire did not harm her. Flames parted around her, and she understood what her parents had died protecting: she was Emberborn, touched by Ignus. She left her old home, uncertain who she could become beyond the weapon she had made of herself.\n\nSix strangers, six lessons\n\nOn the road, Kira, a merchant’s daughter, showed her what cooperation could accomplish. An arthritic healer taught her that sanctuary can be made through presence rather than force. A grieving farmer and a preserved lemon gave her a way to understand bitterness as something that could be transformed.\n\nA mercenary captain showed her the strength of shared purpose. A philosophy scholar asked her to find the principle beneath the technique. A monastery abbot asked who she might be after violence. In that silence, she began to hear a current beneath her fear.\n\nBeyond the mists\n\nWhen Talia entered Hynafol, the fire in her blood awakened fully. Later, a rediscovered manuscript gave a name to the lessons she had already been living. The Current had not given her those experiences; it had given her a way to bring them together.\n\nShe now tends the faith’s sacred objects, its Circles and its seekers. Her personal oath to the Court of Valor does not bind the Current or its members. Within the faith, many allegiances may gather without surrendering their own paths.\n\nThe story continues\n\nAt the November 2025 Grand Gathering, the working for Ophelia’s heart revealed Talia’s Emberborn nature publicly. The Keeper’s Beacon followed in February 2026. At the March 2026 Trials expedition, she rose after an assassination and stood for the Unity Mead that evening.\n\nThis introduction is drawn from Talia’s Hynafol wiki biography. The complete account—including the workings and their witnesses—continues at the link below."}',1,unixepoch()*1000 FROM seekers WHERE email_normalized='talia.emberborn@gmail.com' ORDER BY created_at,id LIMIT 1;
INSERT INTO chronicles(id,draft,published,updated_at) VALUES('ophelia-heart','{"date": "2025-11", "title": "The Working for Ophelia’s Heart", "summary": "A Circle of Truth, a vow enforced, and the Keeper’s fire witnessed.", "body": "At the Grand Gathering of November 2025, the Keeper convened a Circle of Truth at Willow’s urging after Sin took Ophelia’s heart. The bargain between Sin and BearClaw was spoken within the Circle.\n\nWhen the heart was withheld, Talia called the broken vow to account. Those gathered held a circle of steel while the heart was surrendered. Corrupted by Sin, it could not simply be returned.\n\nThe Keeper let her Emberborn fire pass through the heart, fed by the shared intention of the gathered souls. The corruption was burned away, and the heart was restored to Ophelia. This was the first widely witnessed revelation of Talia’s fire.\n\nThe full wiki chronicle records the bargain, the witnesses and the consequences that remained.", "video": "uHmgQvJRZGc", "author": "From the recorded accounts of the Current", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn"}','{"date": "2025-11", "title": "The Working for Ophelia’s Heart", "summary": "A Circle of Truth, a vow enforced, and the Keeper’s fire witnessed.", "body": "At the Grand Gathering of November 2025, the Keeper convened a Circle of Truth at Willow’s urging after Sin took Ophelia’s heart. The bargain between Sin and BearClaw was spoken within the Circle.\n\nWhen the heart was withheld, Talia called the broken vow to account. Those gathered held a circle of steel while the heart was surrendered. Corrupted by Sin, it could not simply be returned.\n\nThe Keeper let her Emberborn fire pass through the heart, fed by the shared intention of the gathered souls. The corruption was burned away, and the heart was restored to Ophelia. This was the first widely witnessed revelation of Talia’s fire.\n\nThe full wiki chronicle records the bargain, the witnesses and the consequences that remained.", "video": "uHmgQvJRZGc", "author": "From the recorded accounts of the Current", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn"}',unixepoch()*1000);
INSERT INTO chronicles(id,draft,published,updated_at) VALUES('keepers-beacon','{"date": "2026-02", "title": "The Keeper’s Beacon", "summary": "A guiding flame for souls seeking their way home.", "body": "The first Keeper’s Beacon was lit in February 2026: a torch kindled in the centre of the Circle.\n\nIts flame marks a place to be witnessed and to offer freely—a gathering of the Current wherever the Keepers stand together. Any soul approaching in good faith may find a welcome there.", "video": "", "author": "From the recorded accounts of the Current", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn"}','{"date": "2026-02", "title": "The Keeper’s Beacon", "summary": "A guiding flame for souls seeking their way home.", "body": "The first Keeper’s Beacon was lit in February 2026: a torch kindled in the centre of the Circle.\n\nIts flame marks a place to be witnessed and to offer freely—a gathering of the Current wherever the Keepers stand together. Any soul approaching in good faith may find a welcome there.", "video": "", "author": "From the recorded accounts of the Current", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn"}',unixepoch()*1000);
INSERT INTO chronicles(id,draft,published,updated_at) VALUES('unity-mead','{"date": "2026-03", "title": "The Unity Mead", "summary": "Twenty banners and many faiths contribute to a shared working.", "body": "At the Trials expedition in March 2026, twenty banners, faiths, kingdoms and individuals offered honey, spirit and other gifts into a sanctified brewing hosted by the Keepers of the Current. Each contribution received the High Priestess’s blessing.\n\nThree covenants were named: the Weight of Many, the Current’s Warning and the Covenant’s Memory. Allied clergy stood with the working, and Lysus Maowulf rose to priesthood and performed his first rite at the gathering.\n\nEarlier that day, Talia had been assassinated. She rose and stood for the working that evening. Twice, unknown hands attempted to break the ritual circle from outside. The circle held.\n\nThe wiki preserves the fuller account and the question that remained unresolved after the assassination.", "video": "", "author": "From the recorded accounts of the Current", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn"}','{"date": "2026-03", "title": "The Unity Mead", "summary": "Twenty banners and many faiths contribute to a shared working.", "body": "At the Trials expedition in March 2026, twenty banners, faiths, kingdoms and individuals offered honey, spirit and other gifts into a sanctified brewing hosted by the Keepers of the Current. Each contribution received the High Priestess’s blessing.\n\nThree covenants were named: the Weight of Many, the Current’s Warning and the Covenant’s Memory. Allied clergy stood with the working, and Lysus Maowulf rose to priesthood and performed his first rite at the gathering.\n\nEarlier that day, Talia had been assassinated. She rose and stood for the working that evening. Twice, unknown hands attempted to break the ritual circle from outside. The circle held.\n\nThe wiki preserves the fuller account and the question that remained unresolved after the assassination.", "video": "", "author": "From the recorded accounts of the Current", "source": "https://hynafol.wiki.gg/wiki/Talia_Emberborn"}',unixepoch()*1000);
